function getIconSvg(iconName, color = '#FFFFFF', size = 22) {
  if (ICONS_MAP[iconName]) {
    return '<svg width="' + size + '" height="' + size + '" viewBox="0 0 24 24">' + ICONS_MAP[iconName].replaceAll('COLOR', color) + '</svg>';
  }
  let paths = APP_DATA.iconPaths[iconName] || APP_DATA.iconPaths[iconName + '___'];
  if (paths && paths.length > 0) {
    const validPaths = paths.filter(p => !p.includes('24,24') && !p.includes('24v24') && !p.includes('24V0z') && !p.includes('24 L 0,24') && !p.includes('24,0 L 24,24'));
    if (validPaths.length > 0) {
      const pathElements = validPaths.map(d => '<path d="' + d + '" fill="' + color + '" />').join('');
      return '<svg width="' + size + '" height="' + size + '" viewBox="0 0 24 24">' + pathElements + '</svg>';
    }
  }
  return '<svg width="' + size + '" height="' + size + '" viewBox="0 0 24 24" fill="' + color + '"><path d="M12 2.69l5.66 5.66a8 8 0 1 1-11.31 0z"/></svg>';
}


function updateLiveClock() {
  const clockEl = document.getElementById('status-time-clock');
  if (!clockEl) return;
  const now = new Date();
  let hours = now.getHours();
  let mins = now.getMinutes();
  mins = mins < 10 ? '0' + mins : mins;
  clockEl.textContent = hours + ':' + mins;
}

function getWeekDaysConfig(startDay) {
  const now = new Date();
  const dayOfWeek = now.getDay(); // 0 is Sun, 1 is Mon, 6 is Sat
  
  const s = (startDay || '').toLowerCase();
  let targetStart = 1; // default Monday
  if (s.includes('sun')) targetStart = 0;
  else if (s.includes('sat')) targetStart = 6;
  
  let diff = dayOfWeek - targetStart;
  if (diff < 0) diff += 7;
  
  const startOfWeek = new Date(now);
  startOfWeek.setDate(now.getDate() - diff);
  startOfWeek.setHours(0, 0, 0, 0);
  
  const dayLetters = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
  const fullDays = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  
  const days = [];
  for (let i = 0; i < 7; i++) {
    const d = new Date(startOfWeek);
    d.setDate(startOfWeek.getDate() + i);
    
    const dateKey = getISODateKey(d);
    const isToday = (dateKey === state.todayKey);
    const isPast = (dateKey < state.todayKey);
    
    days.push({
      name: dayLetters[d.getDay()],
      day: d.getDate(),
      dateKey: dateKey,
      fullDateName: fullDays[d.getDay()] + ', ' + months[d.getMonth()] + ' ' + d.getDate(),
      isToday: isToday,
      isPast: isPast
    });
  }
  return days;
}

function renderWeekRibbon() {
  const container = document.getElementById('week-ribbon-container');
  if (!container) return;
  const days = getWeekDaysConfig(state.weekStartDay);
  let html = '';
  days.forEach(d => {
    const isToday = d.isToday;
    const isActive = d.dateKey === state.selectedDay;
    const hasCompletions = state.habits.some(h => h.history && h.history[d.dateKey] && h.history[d.dateKey].done);
    html += '<div class="day-pill ' + (isActive ? 'active ' : '') + (isToday ? 'today ' : '') + (hasCompletions ? 'completed ' : '') + '" data-datekey="' + d.dateKey + '" onclick="selectDay(\'' + d.dateKey + '\')" title="' + d.fullDateName + '">';
    html += '<span class="day-name">' + d.name + '</span>';
    html += '<span class="day-num">' + d.day + '</span>';
    html += '<span class="day-dot" style="' + (hasCompletions ? 'background: #0FC580; opacity: 1;' : '') + '"></span>';
    html += '</div>';
  });
  container.innerHTML = html;
}

// Render Date Banner
function renderDateBanner() {
  const banner = document.getElementById('date-view-banner');
  if (!banner) return;
  if (state.isDayToday()) {
    banner.style.display = 'none';
  } else {
    banner.style.display = 'flex';
    const days = getWeekDaysConfig(state.weekStartDay);
    const dayObj = days.find(d => d.dateKey === state.selectedDay);
    const label = dayObj ? dayObj.fullDateName : state.selectedDay;
    const isPast = state.isDayPast();
    banner.innerHTML = '<span>🗓️ Viewing: ' + label + ' (' + (isPast ? 'Past Day' : 'Upcoming') + ')</span><button onclick="selectDay(\'' + state.todayKey + '\')">Back to Today</button>';
  }
}

// Render Today Screen
function renderTodayScreen() {
  const container = document.getElementById('today-habits-container');
  if (!container) return;

  renderDateBanner();

  const headerDayName = document.getElementById('today-day-name');
  const headerDateTitle = document.getElementById('today-date-title');
  const days = getWeekDaysConfig(state.weekStartDay);
  const activeDayObj = days.find(d => d.dateKey === state.selectedDay);
  
  if (headerDayName && activeDayObj) {
    headerDayName.textContent = activeDayObj.fullDateName.toUpperCase();
  }
  if (headerDateTitle) {
    headerDateTitle.textContent = state.isDayToday() ? "Today's Habits" : (activeDayObj ? (activeDayObj.name + ' ' + activeDayObj.day + " Habits") : "Habit Timeline");
  }

  const rate = state.getCompletionRate();
  const total = state.habits.length;
  let completed = 0;
  state.habits.forEach(h => {
    const dayData = h.history[state.selectedDay];
    if (dayData && dayData.done) completed++;
  });

  const gaugeVal = document.getElementById('hero-gauge-val');
  const gaugeText = document.getElementById('hero-gauge-text');
  const heroSubtitle = document.getElementById('hero-motivation-sub');
  const heroTitle = document.getElementById('hero-motivation-title');

  if (gaugeVal) {
    const offset = 220 - (220 * rate) / 100;
    gaugeVal.style.strokeDashoffset = offset;
  }
  if (gaugeText) gaugeText.textContent = rate + '%';
  if (heroSubtitle) heroSubtitle.textContent = total > 0 ? (completed + ' of ' + total + ' completed ' + (state.isDayToday() ? 'today' : 'on selected date')) : 'No habits added yet';
  if (heroTitle) {
    if (total === 0) heroTitle.textContent = 'Ready to begin! ✨';
    else if (rate === 100) heroTitle.textContent = 'All goals done! 🎉';
    else if (rate >= 60) heroTitle.textContent = 'Crushing your habits! 🔥';
    else if (rate > 0) heroTitle.textContent = 'Keep momentum going! 👏';
    else heroTitle.textContent = 'Build your daily streak! 💪';
  }

  // Update Week Ribbon dynamically based on start day of the week
  renderWeekRibbon();

  // If no habits exist, render clean-start empty timeline state
  if (state.habits.length === 0) {
    container.innerHTML = `
      <div class="empty-timeline-card" style="text-align:center; padding: 36px 20px; background: var(--app-bg-card); border-radius: 24px; margin-top: 10px; border: 1px solid rgba(255,255,255,0.06);">
        <div style="width: 72px; height: 72px; border-radius: 50%; background: linear-gradient(135deg, rgba(87,0,203,0.2), rgba(0,98,228,0.2)); display: flex; align-items: center; justify-content: center; margin: 0 auto 16px; font-size: 32px;">✨</div>
        <h3 style="font-size: 20px; font-weight: 800; color: #FFFFFF; margin-bottom: 8px;">No Habits Yet</h3>
        <p style="font-size: 13px; color: var(--app-text-muted); max-width: 280px; margin: 0 auto 20px; line-height: 1.5;">Your timeline is fresh! Choose from curated popular presets or build your custom routine.</p>
        <button class="primary-btn" onclick="openAddHabitSheet()" style="padding: 12px 24px; font-size: 14px; font-weight: 700; border-radius: 14px; border: none; background: linear-gradient(135deg, #5700CB, #0062E4); color: #fff; cursor: pointer; box-shadow: 0 4px 14px rgba(87,0,203,0.4);">+ Add Your First Habit</button>
      </div>
    `;
    return;
  }


  const timeBuckets = [
    { id: 'morning', label: 'Morning', icon: '🌅' },
    { id: 'afternoon', label: 'Afternoon', icon: '☀️' },
    { id: 'evening', label: 'Evening', icon: '🌙' },
    { id: 'anytime', label: 'Anytime', icon: '⏰' }
  ];

  let html = '';

  timeBuckets.forEach(bucket => {
    const habits = state.habits.filter(h => h.timeOfDay === bucket.id);
    if (habits.length === 0) return;

    let bucketCompleted = 0;
    habits.forEach(h => {
      const d = h.history[state.selectedDay];
      if (d && d.done) bucketCompleted++;
    });

    html += '<div class="section-header">';
    html += '<div class="section-title"><span>' + bucket.icon + '</span><span>' + bucket.label + '</span></div>';
    html += '<span class="section-count">' + bucketCompleted + '/' + habits.length + '</span>';
    html += '</div>';

    habits.forEach(habit => {
      const status = state.getHabitStatusOnSelectedDay(habit);
      const isCompleted = status === 'completed';
      const isFatalMissed = status === 'fatal_missed';

      html += '<div class="habit-card ' + (isCompleted ? 'completed' : '') + ' ' + (isFatalMissed ? 'fatal-missed' : '') + '" onclick="onHabitCardClick(event, ' + habit.id + ')">';
      
      // Top Row
      html += '<div class="habit-card-top">';
      html += '<div class="habit-main">';
      html += '<div class="habit-icon-wrapper" style="background: ' + habit.color + '">' + getIconSvg(habit.icon, '#FFFFFF', 22) + '</div>';
      html += '<div class="habit-details">';
      html += '<span class="habit-name">' + habit.name + '</span>';
      
      // Tag Badges
      html += '<div class="habit-tags-row">';
      html += '<span class="habit-tag tag-freq">' + habit.repeatLabel + '</span>';
      if (habit.strictness === 'strict') {
        html += '<span class="habit-tag tag-strict">⚡ Fatal Strict</span>';
      } else if (habit.strictness === 'flexible') {
        html += '<span class="habit-tag tag-flexible">🛡️ Flexible</span>';
      } else if (habit.strictness === 'rollover') {
        html += '<span class="habit-tag tag-rollover">🔄 Rollover</span>';
      }
      html += '<span style="color:#FF7450; font-size:11px; font-weight:700;">🔥 ' + habit.streak + 'd</span>';
      html += '</div>'; // tags-row

      html += '</div>'; // details
      html += '</div>'; // main

      // Check Button
      if (isFatalMissed) {
        html += '<button class="habit-check-btn" title="Missed! Fatal strictness resets streak" disabled>';
        html += '<span style="font-size:14px;">🔒</span>';
        html += '</button>';
      } else {
        html += '<button class="habit-check-btn" onclick="onHabitCheckClick(event, ' + habit.id + ')" aria-label="Toggle habit">';
        html += '<svg viewBox="0 0 24 24"><polyline points="20 6 9 17 4 12"></polyline></svg>';
        html += '</button>';
      }
      html += '</div>'; // habit-card-top

      // Multi-Mode Body Sections
      if (habit.type === 'amount') {
        const dayAmount = (habit.history[state.selectedDay] && habit.history[state.selectedDay].amount !== undefined) ? habit.history[state.selectedDay].amount : (state.isDayToday() ? (habit.currentAmount || 0) : 0);
        const percent = Math.min(100, Math.round((dayAmount / habit.targetAmount) * 100));
        html += '<div class="amount-progress-section">';
        html += '<div class="amount-text-row">';
        html += '<span>' + dayAmount + ' / ' + habit.targetAmount + ' ' + habit.unit + '</span>';
        html += '<span>' + percent + '%</span>';
        html += '</div>';
        html += '<div class="amount-track"><div class="amount-fill" style="width: ' + percent + '%;"></div></div>';
        
        if (!isFatalMissed && !isCompleted) {
          html += '<div class="amount-chip-buttons" onclick="event.stopPropagation()">';
          html += '<button class="amount-chip" onclick="onAddAmount(event, ' + habit.id + ', ' + habit.stepAmount + ')">+' + habit.stepAmount + ' ' + habit.unit + '</button>';
          html += '<button class="amount-chip" onclick="onAddAmount(event, ' + habit.id + ', ' + (habit.stepAmount * 2) + ')">+' + (habit.stepAmount * 2) + ' ' + habit.unit + '</button>';
          html += '</div>';
        }
        html += '</div>'; // amount-progress-section
      } else if (habit.type === 'reps') {
        const dayReps = (habit.history[state.selectedDay] && habit.history[state.selectedDay].reps !== undefined) ? habit.history[state.selectedDay].reps : (state.isDayToday() ? (habit.currentReps || 0) : 0);
        html += '<div class="reps-progress-section">';
        html += '<div class="reps-dots-box">';
        for (let r = 1; r <= habit.targetReps; r++) {
          html += '<div class="rep-dot ' + (r <= dayReps ? 'filled' : '') + '"></div>';
        }
        html += '</div>';
        
        if (!isFatalMissed) {
          html += '<div class="reps-stepper" onclick="event.stopPropagation()">';
          html += '<button class="reps-btn" onclick="onStepReps(event, ' + habit.id + ', -1)">-</button>';
          html += '<span class="reps-count-badge">' + dayReps + ' / ' + habit.targetReps + '</span>';
          html += '<button class="reps-btn" onclick="onStepReps(event, ' + habit.id + ', 1)">+</button>';
          html += '</div>';
        } else {
          html += '<span style="font-size:12px; color:#FF5A5F; font-weight:700;">Streak Missed</span>';
        }
        html += '</div>'; // reps-progress-section
      }

      html += '</div>'; // habit-card
    });
  });

  container.innerHTML = html;
}

function onHabitCheckClick(e, id) {
  e.stopPropagation();
  sound.playClick();
  const completed = state.toggleBinaryHabit(id);
  if (completed) {
    sound.playSuccess();
    const rect = e.target.getBoundingClientRect();
    confetti.burst(rect.left + rect.width / 2, rect.top + rect.height / 2);
    showToast('Goal completed! Streak extended 🔥');
    pulseDynamicIsland('Completed! 🔥');
  }
  renderTodayScreen();
}

function onAddAmount(e, id, step) {
  e.stopPropagation();
  sound.playClick();
  const completed = state.incrementAmount(id, step);
  if (completed) {
    sound.playSuccess();
    confetti.burst();
    showToast('Target reached! Awesome work 🎉');
    pulseDynamicIsland('Target reached! 🎉');
  }
  renderTodayScreen();
}

function onStepReps(e, id, delta) {
  e.stopPropagation();
  sound.playClick();
  const completed = state.stepReps(id, delta);
  if (completed) {
    sound.playSuccess();
    confetti.burst();
    showToast('All repetitions done! 🔥');
    pulseDynamicIsland('Reps finished! 🔥');
  }
  renderTodayScreen();
}

function selectDay(dayNum) {
  state.selectedDay = dayNum;
  sound.playClick();
  renderTodayScreen();
}

function renderHabitDetails(id) {
  const habit = state.habits.find(h => h.id === id);
  if (!habit) return;
  state.selectedHabitId = id;

  const iconEl = document.getElementById('details-hero-icon');
  const titleEl = document.getElementById('details-title');
  const subEl = document.getElementById('details-subtitle');
  const curStreakEl = document.getElementById('details-cur-streak');
  const bestStreakEl = document.getElementById('details-best-streak');
  const totalLogsEl = document.getElementById('details-total-logs');
  const rateEl = document.getElementById('details-rate');
  const calendarEl = document.getElementById('details-cal-grid');

  if (iconEl) {
    iconEl.style.background = habit.color;
    iconEl.innerHTML = getIconSvg(habit.icon, '#FFFFFF', 36);
  }
  if (titleEl) titleEl.textContent = habit.name;
  if (subEl) {
    subEl.textContent = habit.repeatLabel + ' • ' + habit.timeOfDay.toUpperCase() + ' • ' + (habit.strictness === 'strict' ? '⚡ Fatal Strict' : '🛡️ Flexible');
  }
  if (curStreakEl) curStreakEl.textContent = habit.streak + 'd';
  if (bestStreakEl) bestStreakEl.textContent = habit.bestStreak + 'd';
  if (totalLogsEl) totalLogsEl.textContent = habit.totalLogs;
  if (rateEl) {
    const rate = Math.min(100, Math.round((habit.totalLogs / 30) * 100));
    rateEl.textContent = rate + '%';
  }

  if (calendarEl) {
    let daysHtml = '';
    const dayLabels = ['M', 'T', 'W', 'T', 'F', 'S', 'S'];
    dayLabels.forEach(d => {
      daysHtml += '<div class="cal-day-header">' + d + '</div>';
    });
    for (let day = 1; day <= 28; day++) {
      const isDone = habit.history[day] && habit.history[day].done;
      daysHtml += '<div class="cal-cell ' + (isDone ? 'completed' : '') + '">' + day + '</div>';
    }
    calendarEl.innerHTML = daysHtml;
  }
}

function renderSheetView() {
  const presetsView = document.getElementById('sheet-presets-view');
  const customView = document.getElementById('sheet-custom-view');
  const tabPresets = document.getElementById('sheet-tab-presets');
  const tabCustom = document.getElementById('sheet-tab-custom');

  if (state.sheetTab === 'presets') {
    presetsView.style.display = 'block';
    customView.style.display = 'none';
    tabPresets.classList.add('active');
    tabCustom.classList.remove('active');
    renderSheetPresets();
  } else {
    presetsView.style.display = 'none';
    customView.style.display = 'block';
    tabPresets.classList.remove('active');
    tabCustom.classList.add('active');
  }
}

function setSheetTab(tabName) {
  state.sheetTab = tabName;
  sound.playClick();
  renderSheetView();
}

function renderSheetPresets() {
  const tabsContainer = document.getElementById('sheet-cat-tabs');
  const presetsContainer = document.getElementById('sheet-presets-list');
  if (!tabsContainer || !presetsContainer) return;

  let tabsHtml = '';
  APP_DATA.categories.forEach(cat => {
    tabsHtml += '<button class="cat-tab-btn ' + (cat.id === state.activeCategory ? 'active' : '') + '" onclick="onSelectSheetCategory(' + cat.id + ')">';
    tabsHtml += cat.name;
    tabsHtml += '</button>';
  });
  tabsContainer.innerHTML = tabsHtml;

  const filteredPresets = APP_DATA.presets.filter(p => p.categoryIds.includes(state.activeCategory)).slice(0, 14);
  let presetsHtml = '';
  filteredPresets.forEach(preset => {
    presetsHtml += '<div class="preset-row-item" onclick="onCustomizePreset(' + preset.id + ')" title="Tap to customize configuration">';
    presetsHtml += '<div class="preset-row-left">';
    presetsHtml += '<div class="habit-icon-wrapper" style="width: 36px; height: 36px; border-radius: 10px; background: ' + preset.color + '">';
    presetsHtml += getIconSvg(preset.icon, '#FFFFFF', 18);
    presetsHtml += '</div>';
    presetsHtml += '<span>' + preset.name + '</span>';
    presetsHtml += '</div>';
    presetsHtml += '<div class="preset-row-actions">';
    presetsHtml += '<span class="preset-customize-hint">⚙️ Edit</span>';
    presetsHtml += '<button type="button" class="add-preset-btn" onclick="event.stopPropagation(); onAddPresetDirectly(' + preset.id + ')" title="Add directly with 1 tap">+ Add</button>';
    presetsHtml += '</div>';
    presetsHtml += '</div>';
  });
  presetsContainer.innerHTML = presetsHtml;
}

function getPresetConfig(preset) {
  const nameLower = (preset.name || '').toLowerCase();
  let type = 'binary';
  let targetAmount = 2000;
  let unit = 'ml';
  let stepAmount = 250;
  let targetReps = 3;
  let targetDuration = 15;
  let frequency = 'daily';
  let freqLabel = 'Every day (Daily)';
  let strictness = state.defaultStrictness || 'strict';

  if (nameLower.includes('water') || nameLower.includes('drink')) {
    type = 'amount';
    targetAmount = 2000;
    unit = 'ml';
    stepAmount = 250;
  } else if (nameLower.includes('walk') || nameLower.includes('run') || nameLower.includes('bike')) {
    type = 'amount';
    targetAmount = 30;
    unit = 'mins';
    stepAmount = 10;
  } else if (nameLower.includes('read') || nameLower.includes('book')) {
    type = 'amount';
    targetAmount = 20;
    unit = 'pages';
    stepAmount = 5;
  } else if (nameLower.includes('vitamin') || nameLower.includes('pill')) {
    type = 'reps';
    targetReps = 2;
  } else if (nameLower.includes('fruit') || nameLower.includes('veggie')) {
    type = 'reps';
    targetReps = 3;
  } else if (nameLower.includes('pushup')) {
    type = 'reps';
    targetReps = 30;
  } else if (nameLower.includes('meditat') || nameLower.includes('yoga') || nameLower.includes('stretch') || nameLower.includes('exercise')) {
    type = 'timer';
    targetDuration = nameLower.includes('10') ? 10 : 15;
  }

  // Map icon to valid option in the custom habit builder dropdown
  const validIcons = ['ic_drink', 'ic_yoga', 'ic_walking', 'ic_run', 'ic_gym', 'ic_fruit', 'ic_read', 'ic_sleep', 'ic_money', 'ic_pills', 'ic_home'];
  let icon = preset.icon;
  if (!validIcons.includes(icon)) {
    if (nameLower.includes('water') || nameLower.includes('drink')) icon = 'ic_drink';
    else if (nameLower.includes('stretch') || nameLower.includes('meditat') || nameLower.includes('breath') || nameLower.includes('bath') || nameLower.includes('spa')) icon = 'ic_yoga';
    else if (nameLower.includes('run')) icon = 'ic_run';
    else if (nameLower.includes('walk') || nameLower.includes('nature') || nameLower.includes('outside')) icon = 'ic_walking';
    else if (nameLower.includes('gym') || nameLower.includes('workout') || nameLower.includes('pushup') || nameLower.includes('exercise')) icon = 'ic_gym';
    else if (nameLower.includes('eat') || nameLower.includes('food') || nameLower.includes('fruit') || nameLower.includes('cook') || nameLower.includes('dinner') || nameLower.includes('breakfast')) icon = 'ic_fruit';
    else if (nameLower.includes('book') || nameLower.includes('read') || nameLower.includes('article') || nameLower.includes('study')) icon = 'ic_read';
    else if (nameLower.includes('sleep') || nameLower.includes('bed') || nameLower.includes('hotel')) icon = 'ic_sleep';
    else if (nameLower.includes('money') || nameLower.includes('save') || nameLower.includes('expense') || nameLower.includes('bill') || nameLower.includes('budget')) icon = 'ic_money';
    else if (nameLower.includes('vitamin') || nameLower.includes('pill') || nameLower.includes('temperature') || nameLower.includes('health')) icon = 'ic_pills';
    else icon = 'ic_home';
  }

  return {
    name: preset.name,
    icon,
    color: preset.color || '#5700CB',
    timeOfDay: preset.timeOfDay || 'anytime',
    type,
    targetAmount,
    unit,
    stepAmount,
    targetReps,
    targetDuration,
    frequency,
    repeatLabel: freqLabel,
    strictness
  };
}

function onCustomizePreset(presetId) {
  const preset = APP_DATA.presets.find(p => p.id === presetId);
  if (!preset) return;
  sound.playClick();
  const config = getPresetConfig(preset);

  // Pre-fill Custom Habit Builder inputs
  const nameInput = document.getElementById('custom-name-input');
  if (nameInput) nameInput.value = config.name;

  // Set tracking type chips & inputs
  onTrackingModeChange(config.type);

  // Set amounts / units
  const targetAmtEl = document.getElementById('custom-target-amount');
  if (targetAmtEl) targetAmtEl.value = config.targetAmount;

  const unitSelect = document.getElementById('custom-unit-select');
  if (unitSelect) unitSelect.value = config.unit;

  const stepAmtEl = document.getElementById('custom-step-amount');
  if (stepAmtEl) stepAmtEl.value = config.stepAmount;

  // Set reps stepper
  const repsInput = document.getElementById('custom-reps-count');
  if (repsInput) repsInput.value = config.targetReps;

  // Set timer minutes
  const timerSelect = document.getElementById('custom-duration-minutes');
  if (timerSelect) timerSelect.value = config.targetDuration;

  // Frequency
  const freqSelect = document.getElementById('custom-frequency-select');
  if (freqSelect) freqSelect.value = config.frequency;

  // Strictness
  const strictSelect = document.getElementById('custom-strictness-select');
  if (strictSelect) strictSelect.value = config.strictness;

  // Time of Day
  const timeSelect = document.getElementById('custom-time-select');
  if (timeSelect) {
    if (['morning', 'afternoon', 'evening', 'anytime'].includes(config.timeOfDay)) {
      timeSelect.value = config.timeOfDay;
    } else {
      timeSelect.value = 'anytime';
    }
  }

  // Color
  const colorSelect = document.getElementById('custom-color-select');
  if (colorSelect) {
    const hasColor = Array.from(colorSelect.options).some(o => o.value.toLowerCase() === config.color.toLowerCase());
    if (hasColor) {
      colorSelect.value = config.color;
    }
  }

  // Icon
  const iconSelect = document.getElementById('custom-icon-select');
  if (iconSelect) iconSelect.value = config.icon;

  // Switch to Custom Tab
  setSheetTab('custom');

  showToast(`Customizing "${config.name}" 🛠️`);
  if (nameInput) {
    setTimeout(() => nameInput.focus(), 150);
  }
}

function onTrackingModeChange(mode) {
  state.customTrackingMode = mode;
  sound.playClick();
  document.getElementById('form-amount-group').style.display = mode === 'amount' ? 'block' : 'none';
  document.getElementById('form-reps-group').style.display = mode === 'reps' ? 'block' : 'none';
  document.getElementById('form-timer-group').style.display = mode === 'timer' ? 'block' : 'none';

  document.querySelectorAll('.mode-chip').forEach(c => {
    c.classList.toggle('selected', c.dataset.mode === mode);
  });
}

function onHabitCardClick(e, id) {
  sound.playClick();
  renderHabitDetails(id);
  switchScreen('details');
}

function stepCustomRepsInput(delta) {
  const input = document.getElementById('custom-reps-count');
  if (!input) return;
  sound.playClick();
  const current = parseInt(input.value, 10) || 1;
  const nextVal = Math.max(1, Math.min(99, current + delta));
  input.value = nextVal;
}

function renderSettingsScreen() {
  const weekStartSelect = document.getElementById('settings-week-start-select');
  const defaultStrictnessSelect = document.getElementById('settings-default-strictness');
  const finishSelect = document.getElementById('settings-finish-select');
  const soundBtn = document.getElementById('settings-sound-toggle-btn');
  const statsEl = document.getElementById('settings-storage-stats');
  const darkBtn = document.getElementById('theme-btn-dark');
  const lightBtn = document.getElementById('theme-btn-light');

  if (weekStartSelect) weekStartSelect.value = state.weekStartDay;
  if (defaultStrictnessSelect) defaultStrictnessSelect.value = state.defaultStrictness;
  if (finishSelect) finishSelect.value = state.finish;
  if (soundBtn) {
    soundBtn.textContent = state.soundEnabled ? '🔊 Enabled' : '🔇 Muted';
    soundBtn.classList.toggle('active', state.soundEnabled);
  }
  if (darkBtn && lightBtn) {
    darkBtn.classList.toggle('active', state.theme === 'dark');
    lightBtn.classList.toggle('active', state.theme === 'light');
  }
  if (statsEl) {
    let totalLogs = 0;
    state.habits.forEach(h => totalLogs += (h.totalLogs || 0));
    statsEl.textContent = `Version 2.4.0 • ${state.habits.length} Habits • ${totalLogs} Total Logs`;
  }
}

function onWeekStartChange(val) {
  state.weekStartDay = val;
  state.saveSettings();
  sound.playClick();
  renderWeekRibbon();
  renderTodayScreen();
  showToast(`Start day set to ${val.charAt(0).toUpperCase() + val.slice(1)} 🗓️`);
}

function onDefaultStrictnessChange(val) {
  state.defaultStrictness = val;
  state.saveSettings();
  sound.playClick();
  showToast('Default strictness updated ⚡');
}

function setAppTheme(theme) {
  state.theme = theme;
  document.documentElement.dataset.appTheme = theme;
  const btn = document.getElementById('tool-theme-btn');
  if (btn) btn.innerHTML = theme === 'dark' ? '🌙 Dark' : '☀️ Light';
  state.saveSettings();
  sound.playClick();
  renderSettingsScreen();
  showToast(`Theme changed to ${theme.toUpperCase()} 🌓`);
}

function exportUserData() {
  sound.playSuccess();
  const backup = {
    app: 'Productive iOS',
    version: '2.4.0',
    exportedAt: new Date().toISOString(),
    theme: state.theme,
    finish: state.finish,
    weekStartDay: state.weekStartDay,
    defaultStrictness: state.defaultStrictness,
    habits: state.habits
  };
  const blob = new Blob([JSON.stringify(backup, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `productive_backup_${new Date().toISOString().slice(0, 10)}.json`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
  showToast('Data backup exported successfully! 📦');
}

function importUserData(event) {
  const file = event.target.files && event.target.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = (e) => {
    try {
      const data = JSON.parse(e.target.result);
      if (data && Array.isArray(data.habits)) {
        state.habits = data.habits;
        if (data.theme) {
          state.theme = data.theme;
          document.documentElement.dataset.appTheme = state.theme;
        }
        if (data.finish) {
          state.finish = data.finish;
          document.documentElement.dataset.finish = state.finish;
        }
        if (data.weekStartDay) {
          state.weekStartDay = data.weekStartDay;
        }
        if (data.defaultStrictness) {
          state.defaultStrictness = data.defaultStrictness;
        }
        state.saveHabits();
        state.saveSettings();
        sound.playSuccess();
        confetti.burst();
        renderWeekRibbon();
        renderTodayScreen();
        renderSettingsScreen();
        showToast(`Imported ${data.habits.length} habits successfully! 🎉`);
      } else {
        showToast('Invalid backup file format ⚠️');
      }
    } catch (err) {
      showToast('Error reading backup JSON file ⚠️');
    }
  };
  reader.readAsText(file);
  event.target.value = '';
}

function resetToDefaults() {
  if (confirm('Are you sure you want to reset all habits and restart the initial setup wizard?')) {
    localStorage.removeItem('productive_habits_user_v1');
    localStorage.removeItem('productive_settings');
    state.habits = [];
    state.saveHabits();
    state.hasCompletedOnboarding = false;
    state.theme = 'dark';
    state.finish = 'natural';
    state.weekStartDay = 'monday';
    state.defaultStrictness = 'strict';
    state.soundEnabled = true;
    state.saveSettings();
    document.documentElement.dataset.appTheme = 'dark';
    document.documentElement.dataset.finish = 'natural';
    sound.playClick();
    relaunchOnboarding();
    showToast('App reset to initial setup wizard 🔄');
  }
}

function switchScreen(screenName) {
  state.activeScreen = screenName;
  sound.playClick();
  document.querySelectorAll('.screen-view').forEach(s => s.classList.remove('active'));
  const target = document.getElementById('screen-' + screenName);
  if (target) target.classList.add('active');

  const tabBar = document.querySelector('.ios-tab-bar');
  if (tabBar) {
    tabBar.style.display = (screenName === 'onboarding') ? 'none' : 'flex';
  }

  document.querySelectorAll('.tab-item').forEach(t => {
    t.classList.toggle('active', t.dataset.screen === screenName);
  });

  if (screenName === 'settings') {
    renderSettingsScreen();
  }
}

function setOnboardingWeekStart(val) {
  state.weekStartDay = val;
  sound.playClick();
  document.querySelectorAll('#onboarding-week-start-options .onboarding-option-pill').forEach(pill => {
    pill.classList.toggle('selected', pill.dataset.value === val);
  });
}

function setOnboardingTheme(val) {
  state.theme = val;
  setAppTheme(val);
  sound.playClick();
  document.querySelectorAll('#onboarding-theme-options .onboarding-option-pill').forEach(pill => {
    pill.classList.toggle('selected', pill.dataset.value === val);
  });
}

function setOnboardingStrictness(val) {
  state.defaultStrictness = val;
  sound.playClick();
  document.querySelectorAll('#onboarding-strictness-options .onboarding-list-row').forEach(row => {
    const isSel = row.dataset.value === val;
    row.classList.toggle('selected', isSel);
    const check = row.querySelector('.check-mark');
    if (check) check.textContent = isSel ? '✓' : '';
  });
}

function toggleOnboardingSound() {
  state.soundEnabled = !state.soundEnabled;
  sound.playClick();
  const btn = document.getElementById('onboarding-sound-btn');
  if (btn) {
    btn.textContent = state.soundEnabled ? '🔊 Enabled' : '🔇 Muted';
    btn.classList.toggle('active', state.soundEnabled);
  }
}

function finishOnboarding() {
  state.hasCompletedOnboarding = true;
  state.saveSettings();
  sound.playSuccess();
  if (typeof confetti !== 'undefined' && confetti && confetti.burst) {
    confetti.burst();
  }
  showToast('Welcome to Productive! 🚀');
  switchScreen('today');
  renderTodayScreen();
}

function relaunchOnboarding() {
  sound.playClick();
  setOnboardingWeekStart(state.weekStartDay);
  setOnboardingTheme(state.theme);
  setOnboardingStrictness(state.defaultStrictness);
  const btn = document.getElementById('onboarding-sound-btn');
  if (btn) {
    btn.textContent = state.soundEnabled ? '🔊 Enabled' : '🔇 Muted';
    btn.classList.toggle('active', state.soundEnabled);
  }
  switchScreen('onboarding');
}



function pulseDynamicIsland(text) {
  const island = document.getElementById('dynamic-island');
  const title = document.getElementById('island-pulse-title');
  if (title) title.textContent = text;
  if (!island.classList.contains('expanded')) {
    island.style.width = '160px';
    setTimeout(() => {
      if (!island.classList.contains('expanded')) island.style.width = 'var(--island-width)';
    }, 1200);
  }
}

function toggleDynamicIsland() {
  sound.playClick();
  const island = document.getElementById('dynamic-island');
  island.classList.toggle('expanded');
  state.islandExpanded = island.classList.contains('expanded');
}

function triggerActionButton() {
  sound.playHaptic();
  const pending = state.habits.find(h => {
    const s = state.getHabitStatusOnSelectedDay(h);
    return s !== 'completed' && s !== 'fatal_missed';
  });
  if (pending) {
    if (pending.type === 'amount') {
      state.incrementAmount(pending.id, pending.stepAmount);
    } else if (pending.type === 'reps') {
      state.stepReps(pending.id, 1);
    } else {
      state.toggleBinaryHabit(pending.id);
    }
    sound.playSuccess();
    confetti.burst();
    showToast('Quick Logged: ' + pending.name + ' ⚡');
    pulseDynamicIsland('Logged: ' + pending.name);
    renderTodayScreen();
  } else {
    showToast('All habits completed for this date! 🔥');
  }
}

function openAddHabitSheet() {
  sound.playClick();
  renderSheetView();
  document.getElementById('sheet-backdrop').classList.add('active');
}

function closeAddHabitSheet() {
  sound.playClick();
  document.getElementById('sheet-backdrop').classList.remove('active');
}

function onSelectSheetCategory(catId) {
  sound.playClick();
  state.activeCategory = catId;
  renderSheetPresets();
}

function onAddPresetDirectly(presetId) {
  sound.playSuccess();
  const preset = APP_DATA.presets.find(p => p.id === presetId);
  if (preset) {
    const config = getPresetConfig(preset);
    state.addCustomHabit(config);
    closeAddHabitSheet();
    renderTodayScreen();
    showToast('Added: ' + preset.name + ' 🔥');
    confetti.burst();
  }
}

function showToast(message) {
  const toast = document.getElementById('ios-toast');
  if (!toast) return;
  toast.querySelector('.toast-msg').textContent = message;
  toast.classList.add('active');
  setTimeout(() => {
    toast.classList.remove('active');
  }, 2200);
}

function setDeviceFinish(finish) {
  state.finish = finish;
  document.documentElement.dataset.finish = finish;
  document.querySelectorAll('.finish-dot').forEach(d => {
    d.classList.toggle('active', d.dataset.finish === finish);
  });
  sound.playClick();
}

function toggleTheme() {
  state.theme = state.theme === 'dark' ? 'light' : 'dark';
  document.documentElement.dataset.appTheme = state.theme;
  const btn = document.getElementById('tool-theme-btn');
  if (btn) btn.innerHTML = state.theme === 'dark' ? '🌙 Dark' : '☀️ Light';
  sound.playClick();
}

function toggleSound() {
  state.soundEnabled = !state.soundEnabled;
  const btn = document.getElementById('tool-sound-btn');
  if (btn) btn.innerHTML = state.soundEnabled ? '🔊 Sound: ON' : '🔇 Sound: OFF';
  if (state.soundEnabled) sound.playClick();
}

window.addEventListener('DOMContentLoaded', () => {
  confetti = new ConfettiEngine(document.getElementById('confetti-canvas'));
  updateLiveClock();
  setInterval(updateLiveClock, 30000);

  document.documentElement.dataset.appTheme = state.theme;
  if (!state.hasCompletedOnboarding) {
    relaunchOnboarding();
  } else {
    renderTodayScreen();
  }
  renderSettingsScreen();

  document.querySelectorAll('.tab-item').forEach(tab => {
    tab.addEventListener('click', () => {
      const scr = tab.dataset.screen;
      if (scr) switchScreen(scr);
    });
  });

  const island = document.getElementById('dynamic-island');
  island.addEventListener('click', (e) => {
    if (e.target.closest('.island-quick-btn')) {
      e.stopPropagation();
      triggerActionButton();
      return;
    }
    toggleDynamicIsland();
  });

  document.getElementById('hw-action-btn').addEventListener('click', triggerActionButton);

  window.addEventListener('keydown', (e) => {
    if (e.code === 'Space' && e.target.tagName !== 'INPUT') {
      e.preventDefault();
      triggerActionButton();
    }
    if (e.key === 'd' || e.key === 'D') toggleDynamicIsland();
    if (e.key === 't' || e.key === 'T') toggleTheme();
  });

  // Custom Habit Form Submission
  const customForm = document.getElementById('custom-habit-form');
  if (customForm) {
    customForm.addEventListener('submit', (e) => {
      e.preventDefault();
      const name = document.getElementById('custom-name-input').value.trim();
      const type = state.customTrackingMode;
      const targetAmount = document.getElementById('custom-target-amount').value;
      const unit = document.getElementById('custom-unit-select').value;
      const stepAmount = document.getElementById('custom-step-amount').value;
      const targetReps = document.getElementById('custom-reps-count').value;
      const targetDuration = document.getElementById('custom-duration-minutes').value;
      const frequency = document.getElementById('custom-frequency-select').value;
      const freqLabel = document.getElementById('custom-frequency-select').selectedOptions[0].text;
      const strictness = document.getElementById('custom-strictness-select').value;
      const timeOfDay = document.getElementById('custom-time-select').value;
      const color = document.getElementById('custom-color-select').value;
      const icon = document.getElementById('custom-icon-select').value;

      if (!name) return;

      state.addCustomHabit({
        name,
        type,
        targetAmount,
        unit,
        stepAmount,
        targetReps,
        targetDuration,
        frequency,
        repeatLabel: freqLabel,
        strictness,
        timeOfDay,
        color,
        icon
      });

      closeAddHabitSheet();
      renderTodayScreen();
      showToast('Created habit: ' + name + ' 🎉');
      confetti.burst();
    });
  }
});
